ALTER TABLE IB_PROCESS_DEPARTMENTS ADD (DEPARTMENT_GROUP VARCHAR2(20) DEFAULT 'PROCESS' NOT NULL);
ALTER TABLE IB_PROCESS_DEPARTMENTS DROP CONSTRAINT IB_DEPT_CK_AREA;
ALTER TABLE IB_PROCESS_DEPARTMENTS ADD CONSTRAINT IB_DEPT_CK_AREA CHECK (AREA IN ('QMM','MFQ','MFO','MFE','TEF','LOP','LOW','CTG','DBE','QMM-L','GS','HSE','PUQ'));
ALTER TABLE IB_PROCESS_DEPARTMENTS ADD CONSTRAINT IB_DEPT_CK_GROUP CHECK (DEPARTMENT_GROUP IN ('PROCESS','CROSS_FUNCTIONAL'));

-- Historical Excel rows: part number / quantity may be missing (flagged), and each Excel row is loaded once.
ALTER TABLE IB_PROCESS_PALLET_RETURNS MODIFY (RETURNED_PART_NUMBER NULL);
ALTER TABLE IB_PROCESS_PALLET_RETURNS DROP CONSTRAINT IB_PR_CK_QTY;
ALTER TABLE IB_PROCESS_PALLET_RETURNS ADD CONSTRAINT IB_PR_CK_QTY CHECK (IS_LEGACY = 'Y' OR QTY_IMPORTED > 0);
ALTER TABLE IB_PROCESS_PALLET_RETURNS ADD CONSTRAINT IB_PR_CK_PN_REQ CHECK (IS_LEGACY = 'Y' OR RETURNED_PART_NUMBER IS NOT NULL);
ALTER TABLE IB_PROCESS_PALLET_RETURNS ADD CONSTRAINT IB_PR_UQ_LEGACY UNIQUE (LEGACY_SHEET, LEGACY_ROW);

